const auth=()=>({Authorization:"Bearer "+session.access_token,Accept:"application/json"});const status=document.querySelector("#status");document.querySelector("#accountEmail").textContent=session?.user?.email||"";document.querySelector("#welcome").textContent=session?.user?.user_metadata?.full_name?"Welcome back, "+session.user.user_metadata.full_name:"Welcome back";document.querySelector("#signOut").onclick=()=>clearSession();async function api(path,options={}){try{await refreshSession(false)}catch{clearSession();throw new Error("Session expired")}const request=()=>fetch(path,{...options,headers:{...auth(),...(options.headers||{})}});let r=await request();if(r.status===401){try{await refreshSession(true);r=await request()}catch{clearSession();throw new Error("Session expired")}}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||d.details||"Request failed");return d}function safeHttpUrl(value){try{const u=new URL(String(value||""),location.origin);return (u.protocol==="https:"||u.protocol==="http:")?u.href:""}catch{return ""}}const integrationAssets={shopify:"/assets/shopify.webp",redbubble:"/assets/redbubble.webp",etsy:"/assets/etsy.webp",artpal:"/assets/artpal.webp",pinterest:"/assets/pinterest.webp",facebook:"/assets/facebook.webp",instagram:"/assets/instagram.webp",x:"/assets/x.webp"};
