function integrationCard(name,state,detail=""){const key=integrationKey(name);const asset=key?integrationAssets[key]:"";return '<article class="integrationWorkspaceCard">'+(asset?'<img src="'+escapeHtml(asset)+'" alt="">':'<div class="integrationFallback">'+escapeHtml(String(name||"?").slice(0,1).toUpperCase())+'</div>')+'<div><h3>'+escapeHtml(name||"Connection")+'</h3><p>'+escapeHtml(detail||state)+'</p></div><span class="connectionState '+(String(state).toLowerCase()==="connected"?"connected":"")+'">'+escapeHtml(state)+'</span></article>'}
function productCard(p){const image=safeHttpUrl(p.imageUrl||p.image_url||p.image||p.thumbnailUrl||p.thumbnail_url||"");const title=p.title||p.name||"Untitled product";const store=p.storeName||p.store_name||p.storeType||p.store_type||"";return '<article class="product">'+(image?'<img src="'+escapeHtml(image)+'" alt="">':'')+'<div><h3>'+escapeHtml(title)+'</h3><p>'+escapeHtml(store)+'</p></div></article>'}function escapeHtml(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}async function load(){status.className="status";status.textContent="Loading your ArtBoost data…";try{const [p,s]=await Promise.all([api("/products?limit=60"),api("/stores")]);const products=p.products||p.items||[];const stores=s.stores||[];document.querySelector("#productCount").textContent=p.total??products.length;document.querySelector("#storeCount").textContent=s.total??stores.filter(x=>x.connected!==false).length;document.querySelector("#accountState").textContent="Connected";document.querySelector("#products").innerHTML=products.length?products.map(productCard).join(""):'<div class="empty">No products found yet.</div>';status.textContent="Your ArtBoost account is connected to the web workspace."}catch(e){status.className="status error";status.textContent=e.message||"Unable to load workspace.";document.querySelector("#accountState").textContent="Error"}}const viewContent=document.querySelector("#viewContent"),panelTitle=document.querySelector("#panelTitle"),panelEyebrow=document.querySelector("#panelEyebrow");
