async function showStores(){status.className="status";status.textContent="Loading stores…";const d=await api("/stores");const stores=d.stores||[];panelEyebrow.textContent="CONNECTED COMMERCE";panelTitle.textContent="Stores";viewContent.innerHTML=stores.length?'<div class="integrationWorkspaceGrid">'+stores.map(storeCard).join("")+'</div>':'<div class="empty">No stores connected.</div>';document.querySelectorAll("[data-store-sync]").forEach(b=>b.onclick=()=>syncStoreProducts(b.dataset.storeSync,b));document.querySelectorAll("[data-store-disconnect]").forEach(b=>b.onclick=()=>disconnectStore(b.dataset.storeDisconnect,b.dataset.storeName,b));status.textContent=stores.length?"Store connections loaded. Refresh uses the current background catalog importer.":"No stores are connected yet."}
