function automationCard(a){const id=automationIdOf(a),enabled=a?.enabled!==false,name=a?.automation_name||a?.name||a?.store_name||a?.store_type||"Store automation",store=a?.store_name||a?.store_type||"Connected store",platforms=Array.isArray(a?.platforms)&&a.platforms.length?a.platforms.join(", "):"No platforms selected",mode=automationModeLabel(a?.selection_mode),delay=Math.max(Number(a?.repeat_delay_days)||0,0),next=formatAutomationTime(a?.next_run_at),time=a?.posting_time?String(a.posting_time).slice(0,5):"—";return '<article class="automationCard"><div class="automationCardTop"><div><span class="automationStore">'+escapeHtml(store)+'</span><h3>'+escapeHtml(name)+'</h3></div><span class="connectionState '+(enabled?"connected":"")+'">'+(enabled?"Active":"Disabled")+'</span></div><div class="automationMeta"><span><b>Time</b>'+escapeHtml(time)+'</span><span><b>Selection</b>'+escapeHtml(mode)+'</span><span><b>Repeat delay</b>'+delay+' days</span><span><b>Next run</b>'+escapeHtml(next)+'</span></div><p class="automationPlatforms">'+escapeHtml(platforms)+'</p><div class="automationActions">'+(id?'<button class="secondary-btn" data-automation-preview="'+escapeHtml(id)+'">Preview Next</button><button class="secondary-btn" data-automation-run="'+escapeHtml(id)+'">Run Now</button>'+(enabled?'<button class="secondary-btn" data-automation-disable="'+escapeHtml(id)+'">Disable</button>':'<button class="secondary-btn" data-automation-resume="'+escapeHtml(id)+'">Resume</button>'):"")+'</div><div class="automationPreview" data-automation-preview-result="'+escapeHtml(id)+'"></div></article>'}
