function parseGeneratedContent(text){const raw=String(text||"");const read=(name,next)=>{const start=raw.indexOf(name+":");if(start<0)return "";const from=start+name.length+1;const end=next?raw.indexOf(next+":",from):-1;return raw.slice(from,end>=0?end:raw.length).trim()};return {title:read("TITLE","DESCRIPTION"),description:read("DESCRIPTION","HASHTAGS"),hashtags:read("HASHTAGS","CTA"),cta:read("CTA","")}}
async function loadPinterestBoards(select){select.innerHTML='<option value="">Loading boards…</option>';try{const d=await api("/pinterest/boards");const boards=d.items||d.boards||[];select.innerHTML='<option value="">Choose a Pinterest board</option>'+boards.map(b=>'<option value="'+escapeHtml(b.id||"")+'">'+escapeHtml(b.name||"Untitled board")+'</option>').join("");if(boards.length===1)select.value=String(boards[0].id||"");if(!boards.length)select.innerHTML='<option value="">No Pinterest boards available</option>'}catch(e){select.innerHTML='<option value="">Pinterest connection required</option>';status.className="status error";status.textContent=e.message||"Unable to load Pinterest boards."}}
async function publishGeneratedPinterest(button){
  const g=window.artboostGenerated;
  if(!g||g.platform!=="Pinterest"){status.className="status error";status.textContent="Pinterest content is not ready. Generate the content again.";return}
  const board=document.querySelector("#generatedBoard");
  const boardId=board?.value;
  if(!boardId){status.className="status error";status.textContent="Choose a Pinterest board first.";board?.focus();return}
  button.disabled=true;
  button.textContent="Publishing…";
  status.className="status";
  status.textContent="Publishing to Pinterest…";
  try{
    const d=await api("/pinterest/create-pin",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({boardId,title:g.title,description:[g.description,g.hashtags,g.cta].filter(Boolean).join("\n\n"),link:g.productLink,imageUrl:g.imageUrl})});
    status.className="status";
    status.textContent="Published to Pinterest successfully.";
    button.textContent="Published";
    button.dataset.published="true";
    return d;
  }catch(e){
    button.disabled=false;
    button.textContent="Publish to Pinterest";
    status.className="status error";
    status.textContent=e.message||"Pinterest publishing failed.";
  }
}
