async function openConsultantSettings(){const current=consultantDisplayName;const requested=prompt("Consultant display name",current);if(requested===null)return;try{const d=await api("/ai/consultant-preferences",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({consultantName:requested})});consultantDisplayName=d.consultantName||current;panelTitle.textContent=consultantDisplayName;document.querySelector(".consultantHeader h3").textContent=consultantDisplayName;status.className="status";status.textContent="Consultant settings saved."}catch(e){status.className="status error";status.textContent=e.message||"Unable to save Consultant settings."}}
function consultantActionButton(action){const view=CONSULTANT_ACTION_VIEWS[action?.id];if(!view)return "";return '<button type="button" class="consultantAction" data-consultant-view="'+escapeHtml(view)+'">'+escapeHtml(action.label||"Open in ArtBoost")+'</button>'}
function consultantResponseMarkup(d){const steps=Array.isArray(d.steps)&&d.steps.length?'<div class="consultantSteps">'+d.steps.map((x,i)=>'<div><b>'+(i+1)+'</b><span>'+escapeHtml(x)+'</span></div>').join("")+'</div>':"",actions=Array.isArray(d.actions)?d.actions.map(consultantActionButton).join(""):"",follow=Array.isArray(d.followUps)&&d.followUps.length?'<div class="consultantFollowups">'+d.followUps.map(x=>'<button type="button" data-consultant-followup="'+escapeHtml(x)+'">'+escapeHtml(x)+'</button>').join("")+'</div>':"",sources=Array.isArray(d.intelligenceSources)&&d.intelligenceSources.length?'<span>Intelligence: '+escapeHtml(d.intelligenceSources.join(", "))+'</span>':"",confidence=d.confidence?'<span>Confidence: '+escapeHtml(d.confidence)+'</span>':"",evidence=d.evidenceNote?'<p>'+escapeHtml(d.evidenceNote)+'</p>':"";return '<div class="assistantBubble '+escapeHtml(d.severity||"info")+'"><b>ARTBOOST AI</b><p>'+escapeHtml(d.answer||d.message||"No answer text was returned.")+'</p>'+steps+(actions?'<div class="consultantActions">'+actions+'</div>':"")+follow+((sources||confidence||evidence)?'<div class="consultantEvidence">'+sources+confidence+evidence+'</div>':"")+'</div>'}
async function askConsultant(event){event.preventDefault();const input=document.querySelector("#consultantQuestion"),question=input.value.trim();if(!question)return;input.value="";await sendConsultantQuestion(question)}
async function sendConsultantQuestion(question){const messages=document.querySelector("#consultantMessages");if(!messages)return;messages.insertAdjacentHTML("beforeend",'<div class="userBubble"><b>YOU</b><p>'+escapeHtml(question)+'</p></div>');const waiting=document.createElement("div");waiting.className="assistantBubble";waiting.textContent=consultantDisplayName+" is thinking…";messages.appendChild(waiting);const conversation=consultantConversation.slice(-10);try{const d=await api("/ai/assistant",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question,currentScreen:"ai-consultant",appVersion:"web",assistantMode:"consultant",conversation,imageDataUrl:consultantImageDataUrl})});waiting.outerHTML=consultantResponseMarkup(d);consultantConversation.push({role:"user",content:question},{role:"assistant",content:String(d.answer||"")});consultantConversation=consultantConversation.slice(-10);document.querySelectorAll("[data-consultant-followup]").forEach(b=>b.onclick=()=>sendConsultantQuestion(b.dataset.consultantFollowup));document.querySelectorAll("[data-consultant-view]").forEach(b=>b.onclick=()=>showView(b.dataset.consultantView))}catch(e){waiting.textContent=e.message||"The AI Consultant is temporarily unavailable.";waiting.classList.add("error")}messages.scrollTop=messages.scrollHeight}
